CREATE TABLE `con_project_calendars` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL,
  `calendar_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Standard 6-Day Construction Calendar',
  `working_days_per_week` int NOT NULL DEFAULT '6',
  `weekly_off_days` json DEFAULT NULL,
  `working_hours_per_day` decimal(4,1) NOT NULL DEFAULT '8.0',
  `shifts` json DEFAULT NULL,
  `holidays` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `project_id` (`project_id`),
  CONSTRAINT `con_project_calendars_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `prj_projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `con_project_calendars` */


/*Table structure for table `con_project_completions` */

DROP TABLE IF EXISTS `con_project_completions`;

CREATE TABLE `con_project_completions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `completion_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` bigint NOT NULL,
  `target_handover_date` date NOT NULL,
  `actual_completion_date` date DEFAULT NULL,
  `stage_status` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'IN_RECONCILIATION',
