  `cost_variance_amount_bdt` decimal(16,2) NOT NULL DEFAULT '0.00',
  `outstanding_contractor_bills_amount` decimal(16,2) NOT NULL DEFAULT '0.00',
  `retention_money_locked_bdt` decimal(16,2) NOT NULL DEFAULT '0.00',
  `retention_release_authorized` tinyint(1) NOT NULL DEFAULT '0',
  `materials_store_reconciliation_cleared` tinyint(1) NOT NULL DEFAULT '0',
  `equipment_store_reconciliation_cleared` tinyint(1) NOT NULL DEFAULT '0',
  `open_quality_defects_count` int NOT NULL DEFAULT '0',
  `open_safety_incidents_count` int NOT NULL DEFAULT '0',
  `as_built_drawings_submitted` tinyint(1) NOT NULL DEFAULT '0',
  `as_built_drawings_ref_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `om_manuals_submitted` tinyint(1) NOT NULL DEFAULT '0',
  `om_manuals_ref_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `warranties_collected_count` int NOT NULL DEFAULT '0',
  `warranties_summary_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mandatory_items_all_cleared` tinyint(1) NOT NULL DEFAULT '0',
  `permitted_punchlist_exceptions` json DEFAULT NULL,
  `taking_over_certificate_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project_manager_signoff` tinyint(1) NOT NULL DEFAULT '0',
  `pm_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pm_signoff_at` datetime DEFAULT NULL,
  `project_director_signoff` tinyint(1) NOT NULL DEFAULT '0',
  `director_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `director_signoff_at` datetime DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `completion_code` (`completion_code`),
  UNIQUE KEY `project_id` (`project_id`),
  KEY `idx_proj_comp_proj` (`project_id`),
  KEY `idx_proj_comp_status` (`stage_status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `con_project_completions` */


/*Table structure for table `con_punchlist_items` */

