  `net_payable_amount` decimal(14,2) NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_general_ci NOT NULL,
  `accounts_journal_voucher_ref` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_general_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `billing_period_start` date DEFAULT NULL,
  `billing_period_end` date DEFAULT NULL,
  `retention_percent` decimal(5,2) NOT NULL DEFAULT '5.00',
  `material_store_recovery_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `tds_rate` decimal(5,2) NOT NULL DEFAULT '5.00',
  `vds_rate` decimal(5,2) NOT NULL DEFAULT '5.00',
  `approval_signature_chain` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `project_id` bigint DEFAULT NULL,
  `contractor_id` bigint DEFAULT NULL,
  `previous_certified_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `current_gross_bill_value` decimal(14,2) NOT NULL DEFAULT '0.00',
  `cumulative_certified_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `previous_payments_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `net_payable_balance` decimal(14,2) NOT NULL DEFAULT '0.00',
  `other_deductions_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `other_deductions_description` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `penalty_deduction_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `tax_treatment_type` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'STANDARD_TDS_52',
  `vat_treatment_type` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'STANDARD_VDS_7_5',
  `workflow_stage` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'CONTRACTOR_SUBMISSION',
  `current_stage_assignee_role` varchar(64) COLLATE utf8mb4_general_ci DEFAULT 'SITE_ENGINEER',
  `revision_number` int NOT NULL DEFAULT '1',
  `rejection_reason` text COLLATE utf8mb4_general_ci,
  `review_comments` text COLLATE utf8mb4_general_ci,
  `measurement_sheet_urls` text COLLATE utf8mb4_general_ci,
  `site_photo_urls` text COLLATE utf8mb4_general_ci,
  `is_on_hold` tinyint(1) NOT NULL DEFAULT '0',
  `hold_reason` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `hold_by_user_id` bigint DEFAULT NULL,
  `dispute_id` bigint DEFAULT NULL,
  `retention_release_status` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'HELD',
  `retention_release_eligible_date` date DEFAULT NULL,
  `retention_release_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `payment_status` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'UNPAID',
  `paid_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `payment_date` date DEFAULT NULL,
  `payment_method` varchar(64) COLLATE utf8mb4_general_ci DEFAULT 'BANK_TRANSFER',
  `bank_payment_ref` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cheque_reference` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_by_user_id` bigint DEFAULT NULL,
  `verified_by_engineer_id` bigint DEFAULT NULL,
  `verified_by_qs_id` bigint DEFAULT NULL,
  `approved_by_pm_id` bigint DEFAULT NULL,
  `reviewed_by_accounts_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_con_ra_bills_status` (`status`),
  KEY `ix_con_ra_bills_work_order_id` (`work_order_id`),
  CONSTRAINT `con_ra_bills_ibfk_1` FOREIGN KEY (`work_order_id`) REFERENCES `con_work_orders` (`id`),
  CONSTRAINT `con_ra_bills_chk_1` CHECK (json_valid(`approval_signature_chain`))
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

