CREATE TABLE `prj_authority_clearances` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL,
  `clearance_type_id` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `authority_name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'RAJUK',
  `reference_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `application_memo_no` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `approved_memo_no` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `approval_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `validity_months` int NOT NULL DEFAULT '12',
  `renewal_reminder_days` int NOT NULL DEFAULT '30',
  `renewal_fee_bdt` decimal(14,2) NOT NULL DEFAULT '0.00',
  `renewal_alert_status` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'VALID',
  `sanctioned_floors` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sanctioned_height_m` decimal(8,2) DEFAULT NULL,
  `contact_officer_name` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contact_officer_phone` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_general_ci NOT NULL,
  `document_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remarks` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `approval_category` varchar(64) COLLATE utf8mb4_general_ci DEFAULT 'BUILDING_PLAN',
  `submission_date` date DEFAULT NULL,
  `responsible_officer` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `next_action` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_prj_authority_clearances_project_id` (`project_id`),
  KEY `ix_prj_authority_clearances_status` (`status`),
  KEY `ix_prj_authority_clearances_clearance_type_id` (`clearance_type_id`),
  CONSTRAINT `prj_authority_clearances_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `prj_projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `prj_authority_clearances` */


/*Table structure for table `prj_boq_items` */

