  `equipment_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `subcontract_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `stage` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'APPROVED_CONTRACT_BOQ',
  `tender_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000',
  `tender_unit_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `tender_total_amount` decimal(16,2) NOT NULL DEFAULT '0.00',
  `contract_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000',
  `contract_unit_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `contract_total_amount` decimal(16,2) NOT NULL DEFAULT '0.00',
  `revised_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000',
  `revised_unit_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `revised_total_amount` decimal(16,2) NOT NULL DEFAULT '0.00',
  `completed_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000',
  `remaining_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000',
  `actual_cost` decimal(16,2) NOT NULL DEFAULT '0.00',
  `cost_variance` decimal(16,2) NOT NULL DEFAULT '0.00',
  `version_no` int NOT NULL DEFAULT '1',
  `approved_by` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `approval_date` date DEFAULT NULL,
  `rate_analysis_notes` text COLLATE utf8mb4_general_ci,
  `supporting_document_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_prj_boq_items_wbs_phase_id` (`wbs_phase_id`),
  KEY `ix_prj_boq_items_tower_id` (`tower_id`),
  KEY `ix_prj_boq_items_material_category_id` (`material_category_id`),
  KEY `ix_prj_boq_items_project_id` (`project_id`),
  CONSTRAINT `prj_boq_items_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `prj_projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `prj_boq_items_ibfk_2` FOREIGN KEY (`tower_id`) REFERENCES `prj_towers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

