  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `user_id` bigint DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `microservice_name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `entity_name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `entity_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `action_type` enum('CREATE','UPDATE','DELETE','CUSTOM') COLLATE utf8mb4_general_ci NOT NULL,
  `payload_before` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `payload_after` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  PRIMARY KEY (`id`,`created_at`),
  KEY `ix_sys_audit_trails_entity_name` (`entity_name`),
  KEY `ix_sys_audit_trails_user_id` (`user_id`),
  KEY `idx_audit_user_created` (`user_id`,`created_at`),
  KEY `idx_audit_entity_name_id` (`entity_name`,`entity_id`),
  CONSTRAINT `sys_audit_trails_chk_1` CHECK (json_valid(`payload_before`)),
  CONSTRAINT `sys_audit_trails_chk_2` CHECK (json_valid(`payload_after`))
) ENGINE=InnoDB AUTO_INCREMENT=1022 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
/*!50100 PARTITION BY RANGE (year(`created_at`))
(PARTITION p2023 VALUES LESS THAN (2024) ENGINE = InnoDB,
 PARTITION p2024 VALUES LESS THAN (2025) ENGINE = InnoDB,
 PARTITION p2025 VALUES LESS THAN (2026) ENGINE = InnoDB,
 PARTITION p2026 VALUES LESS THAN (2027) ENGINE = InnoDB,
 PARTITION p2027 VALUES LESS THAN (2028) ENGINE = InnoDB,
 PARTITION p_max VALUES LESS THAN MAXVALUE ENGINE = InnoDB) */;

