insert  into `sls_registration_checklist_templates`(`id`,`template_code`,`template_name`,`description`,`property_type`,`checklist_schema`,`is_active`,`created_at`,`updated_at`) values 
(1,'STANDARD_RESIDENTIAL_APARTMENT','Standard Residential Apartment Registration Checklist','Statutory 9-stage legal compliance workflow under Registration Act 1908 & REHAB norms.','RESIDENTIAL_APARTMENT','[{\"id\": \"item_1_buyer_agreement\", \"title\": \"Agreement & Buyer Details Verified\", \"mandatory\": true, \"description\": \"Verify signed agreement for sale, primary customer NID/Passport, co-buyers, and KYC profiles.\", \"step_number\": 1, \"required_docs\": [\"Signed Agreement for Sale\", \"Buyer NID Copies\", \"TIN Certificate\", \"KYC Declaration\"]}, {\"id\": \"item_2_property_docs\", \"title\": \"Property Identification & Approved Documents Available\", \"mandatory\": true, \"description\": \"Confirm floor, unit number, car parking allotment, RAJUK/CDA approved building plan & occupancy clearance.\", \"step_number\": 2, \"required_docs\": [\"Approved Architectural Floor Plan\", \"Unit Allocation Letter\", \"RAJUK Approval Memo\"]}, {\"id\": \"item_3_payment_fees\", \"title\": \"Required Payment & Fee Status Checked\", \"mandatory\": true, \"description\": \"Verify full consideration clearance, registration cost settlement, stamp duty, AIT (u/s 53FF), and local taxes.\", \"step_number\": 3, \"required_docs\": [\"Final Payment Clearance Certificate\", \"Stamp Duty Pay Order\", \"AIT Tax Challan\", \"Local Gov Tax Receipt\"]}, {\"id\": \"item_4_title_mutation_tax\", \"title\": \"Applicable Title, Mutation, Tax & Supporting Records Collected\", \"mandatory\": true, \"description\": \"Compile CS, SA, RS, City Jarip Khatians, Bia Deeds, Namjari Porcha, DCR, and updated Land Development Tax (Khajna).\", \"step_number\": 4, \"required_docs\": [\"CS/SA/RS/City Jarip Khatian\", \"Bia Deeds (25-year chain)\", \"Mutation Porcha & DCR\", \"Updated Khajna Receipt\"]}, {\"id\": \"item_5_draft_deed_review\", \"title\": \"Draft Deed Prepared & Legal Review Completed\", \"mandatory\": true, \"description\": \"Drafting of Saf Kabala on prescribed non-judicial stamp papers by certified deed writer / High Court advocate.\", \"step_number\": 5, \"required_docs\": [\"Draft Sale Deed Vetted Copy\", \"Legal Counsel Approval Memo\"]}, {\"id\": \"item_6_appointment_scheduled\", \"title\": \"Registration Appointment Scheduled\", \"mandatory\": true, \"description\": \"Coordination with Sub-Registry Office, Sub-Registrar appointment date booking, and executing parties coordination.\", \"step_number\": 6, \"required_docs\": [\"Sub-Registry Appointment Slip\", \"Parties Identification Memo\"]}, {\"id\": \"item_7_submission_recorded\", \"title\": \"Submission & Registration Reference Recorded\", \"mandatory\": true, \"description\": \"Record official token, deed receipt number (I-Form), balam book volume, and page reference.\", \"step_number\": 7, \"required_docs\": [\"Sub-Registry I-Form Receipt\", \"Token Slip\"]}, {\"id\": \"item_8_registered_deed_received\", \"title\": \"Registered Deed / Certified Evidence Received\", \"mandatory\": true, \"description\": \"Collection of original registered deed from Sub-Registry or certified true copy (Nokol), archived into document vault.\", \"step_number\": 8, \"required_docs\": [\"Original Registered Sale Deed\", \"Certified Balam Copy (Nokol)\", \"Document Vault Certificate\"]}, {\"id\": \"item_9_legal_issues_tracking\", \"title\": \"Outstanding Legal Issues & Corrective Actions Tracked\", \"mandatory\": false, \"description\": \"Track any Sub-Registry queries, name corrections, boundary amendments, or certified endorsement rectification.\", \"step_number\": 9, \"required_docs\": [\"Legal Query Sheet\", \"Correction / Rectification Deed (if any)\"]}]',1,'2026-10-18 21:39:59','2026-10-18 21:39:59');
