insert  into `sys_permissions`(`id`,`module_code`,`permission_code`,`permission_name`,`description`,`is_active`,`created_at`) values 
(19,'PROCUREMENT','PROC_DASHBOARD_VIEW','View Procurement & Inventory Dashboard','View KPI counters, PO spending analytics, pending approvals, and low stock alerts',1,'2026-10-18 15:16:35'),
(20,'PROCUREMENT','PROC_VENDOR_MANAGE','Supplier & Vendor Management','Register, evaluate, approve, suspend suppliers, and monitor trade license expiry',1,'2026-10-18 15:16:35'),
(21,'PROCUREMENT','PROC_MATERIAL_MANAGE','Material & Item Master Management','Create and manage material codes, specifications, categories, and unit conversions',1,'2026-10-18 15:16:35'),
(22,'PROCUREMENT','PROC_PR_CREATE','Create Purchase Requisitions','Initiate material requisitions against project WBS and BOQ budget allocations',1,'2026-10-18 15:16:35'),
(23,'PROCUREMENT','PROC_PR_APPROVE','Approve Purchase Requisitions','Department and budget authority review and sign-off on material requisitions',1,'2026-10-18 15:16:35'),
(24,'PROCUREMENT','PROC_RFQ_MANAGE','RFQ & Comparative Statement','Issue RFQs to enlisted vendors, input quotations, and evaluate commercial CS',1,'2026-10-18 15:16:35'),
(25,'PROCUREMENT','PROC_PO_CREATE','Create Purchase Orders','Draft purchase orders against approved requisitions and awarded quotations',1,'2026-10-18 15:16:35'),
(26,'PROCUREMENT','PROC_PO_APPROVE','Multi-Tier PO Approval','Authorize purchase orders based on financial delegated authority limits',1,'2026-10-18 15:16:35'),
(27,'PROCUREMENT','PROC_GRN_RECEIVE','Goods Receipt Note (GRN) & Gate Entry','Record physical challan arrival, vehicle gate entry, count verification and unloading',1,'2026-10-18 15:16:35'),
(28,'PROCUREMENT','PROC_QC_INSPECT','Quality Inspection & Testing','Perform material quality control tests (tensile, slump, moisture), accept or reject batches',1,'2026-10-18 15:16:35'),
(29,'PROCUREMENT','PROC_STOCK_MANAGE','Warehouse & Site Stock Management','Manage central and site stores, bin/rack locations, batches, and reorder levels',1,'2026-10-18 15:16:35'),
(30,'PROCUREMENT','PROC_MIN_ISSUE','Material Issue Note & Consumption','Issue materials to site engineers/contractors, record returns, wastage and BOQ consumption',1,'2026-10-18 15:16:35'),
(31,'PROCUREMENT','PROC_TRANSFER_MANAGE','Stock Transfers & Adjustments','Execute warehouse-to-site transfers, in-transit tracking, and cycle-count stock adjustments',1,'2026-10-18 15:16:35'),
(32,'PROCUREMENT','PROC_PLANNING_MANAGE','Material Planning & Reorder Replenishment','Monitor safety stocks, lead-time planning, and automated purchase replenishment indents',1,'2026-10-18 15:16:35'),
(33,'PROCUREMENT','PROC_VALUATION_VIEW','Perpetual Valuation & Inventory Ledger','View AVCO/FIFO/Standard costing valuations, store ledgers, and GL reconciliation',1,'2026-10-18 15:16:35'),
(34,'PROCUREMENT','PROC_BILL_MATCH','Supplier 3-Way Match & Reconcile','Perform three-way matching (PO vs GRN vs Supplier Invoice) and manage variances',1,'2026-10-18 15:16:35'),
(35,'PROCUREMENT','PROC_BILL_PAY','Accounts Payable Disbursement & Vouchers','Disburse payments, issue bank payment vouchers, and manage supplier debit notes',1,'2026-10-18 15:16:35'),
(36,'PROCUREMENT','PROC_AUDIT_VIEW','Procurement Audit Trail & Reports','Access full immutable audit trail, historical price trends, and vendor scorecards',1,'2026-10-18 15:16:35');
